import numpy as np
from scipy.optimize import minimize_scalar
import itertools
P=lambda p:(lambda t:t**p)
Abasis={'1':P(0),'T':P(1),'T2':P(2),'T3':P(3),'T4':P(4),'1/T':lambda t:1/t,'1/T2':lambda t:t**-2.0,'lnT':np.log,'1/T3':lambda t:t**-3.0,'T5':P(5)}
Bbasis={'1/T':lambda t:1/t,'1/T2':lambda t:t**-2.0,'1':P(0),'T':P(1)}
def run(k,A,B):
    E=eps*np.exp(-k*eps)
    X=np.column_stack([f(T) for f in A]+[E*f(T) for f in B])
    c,_,_,_=np.linalg.lstsq(X,sigma,rcond=None)
    r=sigma-X@c
    return np.mean(r**2)/np.var(sigma), c
res=[]
keysA=list(Abasis)
for bk in Bbasis:
    B=[Bbasis[bk]]
    for n in range(2,6):
        for combo in itertools.combinations(keysA,n):
            A=[Abasis[c] for c in combo]
            r2=minimize_scalar(lambda k: run(k,A,B)[0],bounds=(0.6,0.9),method='bounded')
            res.append((r2.fun,bk,combo,r2.x))
res.sort(key=lambda z:z[0])
for r_ in res[:10]: print(r_)
